//! 24 类计算产物的有界记录与严格前缀复用；记录失败不能改变交易计算。
use super::{ArtifactCache,StoreResult,StoreError,canonical,sha256,require};
use super::calculation_chunk::{EvidenceJsonCache,TrendChunk,restore_calculation_chunk,MAX_EXPANDED_BYTES};
use serde::{Serialize,Deserialize};
use crate::indexed_json::{Value,json};
use sha2::{Sha256,Digest};
use std::{collections::{BTreeMap,BTreeSet},sync::{Arc,atomic::{AtomicU64,Ordering}},time::Instant};
const TITLES:[&str;24]=["算技术折线","计算 N 字目标位","计算一级趋势线","一级·空翻多位置","一级·空多交替位置","一级·确认转多位置","一级·多翻空位置","一级·多空交替位置","一级·确认转空位置","计算二级趋势线","二级·空翻多位置","二级·空多交替位置","二级·确认转多位置","二级·多翻空位置","二级·多空交替位置","二级·确认转空位置","计算三级趋势线","三级·空翻多位置","三级·空多交替位置","三级·确认转多位置","三级·多翻空位置","三级·多空交替位置","三级·确认转空位置","多级协同与 B/S 信号及回测"];
static NEXT_ATTEMPT:AtomicU64=AtomicU64::new(1);
fn step_level(step:u8)->Option<u8>{match step{1=>Some(0),3..=9=>Some(1),10..=16=>Some(2),17..=23=>Some(3),_=>None}}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]
pub struct CalculationPlan{pub requested_order:Vec<u8>,pub execution_order:Vec<u8>}
impl CalculationPlan{pub fn resolve(order:Option<&[u8]>)->StoreResult<Self>{let mut requested=Vec::new();let mut seen=BTreeSet::new();for step in order.unwrap_or(&[1,3,10,17,2,24]){require((1..=24).contains(step)&&seen.insert(*step),"calculation steps must be unique integers 1..24")?;requested.push(*step);}for step in 1..=24{if seen.insert(step){requested.push(step);}}Ok(Self{requested_order:requested,execution_order:vec![1,3,10,17,2,24]})}}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]
pub struct CalculationReuseCertificate{pub schema:u32,pub timeframe:String,pub trend_level:Option<u8>,pub market_sha256:String,pub request_sha256:String,pub engine_sha256:String,pub bar_count:usize,pub step:u8,pub through_index:usize,pub chunks_sha256:String}
#[derive(Debug,Clone,Serialize,Deserialize)]
pub struct CalculationChunkRef{pub key:Value,pub sha256:String,pub rows:usize,pub through_index:usize}
#[derive(Debug,Clone,Serialize,Deserialize)]
pub struct CalculationStep{pub id:u8,pub title:String,pub status:String,pub cache:String,pub rows:usize,pub chunks:Vec<CalculationChunkRef>,pub through_index:Option<usize>,pub elapsed_seconds:f64,pub encoding_seconds:f64,pub write_seconds:f64,pub encoded_bytes:usize,pub reused_bytes:usize,#[serde(skip_serializing_if="Option::is_none")]pub error:Option<String>}
struct Buffer{rows:Vec<Value>,bytes:usize,through:usize,chunk:Option<TrendChunk>}
pub struct CalculationStepCache{cache:Option<Arc<ArtifactCache>>,identity:Value,timeframe:String,inputs:Option<Value>,attempt:String,record_details:bool,pub cache_disabled:bool,steps:Vec<CalculationStep>,buffers:BTreeMap<u8,Buffer>,started:BTreeMap<u8,Instant>,evidence:EvidenceJsonCache,plan:CalculationPlan,bar_count:usize}
impl CalculationStepCache{
    pub fn new(cache:Option<Arc<ArtifactCache>>,identity:Value,record_details:bool)->StoreResult<Self>{require(identity.is_object(),"calculation identity must be explicit object")?;let timeframe=identity.get("timeframe").and_then(Value::as_str).filter(|v|!v.is_empty()&&v.trim()==*v&&v.len()<=64&&!v.chars().any(char::is_control)).ok_or_else(||StoreError("calculation identity requires explicit K-line timeframe".into()))?.to_owned();let attempt=format!("{}-{}-{}",std::process::id(),chrono::Utc::now().timestamp_micros(),NEXT_ATTEMPT.fetch_add(1,Ordering::Relaxed));let steps=TITLES.iter().enumerate().map(|(i,title)|CalculationStep{id:(i+1)as u8,title:(*title).into(),status:"pending".into(),cache:"none".into(),rows:0,chunks:vec![],through_index:None,elapsed_seconds:0.0,encoding_seconds:0.0,write_seconds:0.0,encoded_bytes:0,reused_bytes:0,error:None}).collect();Ok(Self{cache,identity,timeframe,inputs:None,attempt,record_details,cache_disabled:false,steps,buffers:BTreeMap::new(),started:BTreeMap::new(),evidence:EvidenceJsonCache::new(8*1024*1024)?,plan:CalculationPlan::resolve(None)?,bar_count:0})}
    pub fn set_plan(&mut self,plan:CalculationPlan)->StoreResult<()>{require(self.started.is_empty()||self.plan==plan,"calculation plan cannot change after processing begins")?;require(plan.execution_order==[1,3,10,17,2,24],"calculation must propagate each date through the unified levels")?;self.plan=plan;Ok(())}
    fn row(&self,step:u8)->StoreResult<&CalculationStep>{self.steps.get(step.checked_sub(1).ok_or_else(||StoreError("invalid calculation step".into()))?as usize).ok_or_else(||StoreError("invalid calculation step".into()))}
    pub fn bind<T:Serialize>(&mut self,bars:&[T])->StoreResult<bool>{if bars.is_empty(){return Ok(false);}let mut hash=Sha256::new();for bar in bars{let value=crate::indexed_json::to_value(bar)?;hash.update(canonical(&value)?);hash.update(b"\n");}let market=format!("{:x}",hash.finalize());let inputs=json!({"schema":5,"timeframe":self.timeframe,"request":self.identity,"request_sha256":sha256(canonical(&self.identity)?),"market_sha256":market,"engine_sha256":crate::infrastructure::computation::engine_identity(),"bar_count":bars.len()});if let Some(old)=&self.inputs{return Ok(*old==inputs);}self.inputs=Some(inputs.clone());self.bar_count=bars.len();
        if self.record_details{if let Some(cache)=&self.cache{if let Some(manifest)=cache.get("calculation-manifest",&inputs){if let Ok(old)=crate::indexed_json::from_value::<Vec<CalculationStep>>(manifest["steps"].clone()){if old.len()==24{for(index,mut row)in old.into_iter().enumerate(){if index<23&&row.id as usize==index+1&&row.status=="completed"&&row.cache=="stored"&&row.through_index.is_some_and(|v|v<bars.len())&&row.chunks.iter().all(|chunk|chunk.through_index<bars.len()&&cache.contains("calculation-chunk",&chunk.key)){row.status="pending".into();row.cache="available".into();row.elapsed_seconds=0.0;row.encoding_seconds=0.0;row.write_seconds=0.0;row.encoded_bytes=0;row.reused_bytes=0;self.steps[index]=row;}}}}}}}Ok(true)
    }
    pub fn snapshot(&self)->Value{let rows:Vec<_>=self.steps.iter().map(|step|{let mut step=step.clone();if step.status=="running"{step.elapsed_seconds=self.started.get(&step.id).map_or(0.0,|at|at.elapsed().as_secs_f64());}let mut value=json!(step);if let Some(map)=value.as_object_mut(){map.remove("chunks");map.insert("timeframe".into(),json!(self.timeframe));map.insert("trend_level".into(),json!(step_level(step.id)));}value}).collect();json!({"schema_version":2,"timeframe":self.timeframe,"steps":rows,"requested_order":self.plan.requested_order,"execution_order":self.plan.execution_order,"record_details":self.record_details,"cache_disabled":self.cache_disabled,"evidence_memory_bytes":self.evidence.memory_bytes(),"note":"同一K线周期内，0为折线、1/2/3为一级/二级/三级；逐根同日传播，不把层级转换成日/周/月。24项为产物身份，不能相加为计算进度。缓存证书不代替未来时点的领域计算。"})}
    pub fn begin(&mut self,step:u8)->StoreResult<()>{self.row(step)?;let row=&mut self.steps[step as usize-1];if row.status!="pending"{return Ok(());}row.status="running".into();if self.record_details&&row.cache!="available"{row.cache=if self.cache_disabled{"partial"}else{"buffering"}.into();}self.started.insert(step,Instant::now());Ok(())}
    /// through_index 是该行真正已知时点；跨未来前缀的块不会获得复用证书。
    pub fn append_at(&mut self,step:u8,through_index:usize,row:&Value)->StoreResult<()>{require(self.inputs.is_some()&&through_index<self.bar_count,"calculation observation outside bound snapshot")?;require(row.is_object(),"calculation row must be object")?;require(row.get("timeframe").is_none_or(|v|v.as_str()==Some(self.timeframe.as_str())),"calculation row timeframe mismatch")?;let mut row=row.clone();row["timeframe"]=json!(self.timeframe);if let Some(level)=step_level(step){require(row.get("trend_level").is_none_or(|v|v.as_u64()==Some(u64::from(level))),"calculation row level does not match product")?;row["trend_level"]=json!(level);}let row=&row;if self.row(step)?.status=="completed"{return Ok(());}self.begin(step)?;if self.row(step)?.cache=="available"{return Ok(());}let index=step as usize-1;if self.steps[index].through_index.is_some_and(|old|old>through_index){return Err(StoreError("calculation observations must not run backwards".into()));}self.steps[index].through_index=Some(through_index);
        if !self.record_details||self.cache_disabled{self.steps[index].rows+=1;return Ok(());}let started=Instant::now();let reused=self.evidence.reused_bytes;let buffer=self.buffers.entry(step).or_insert_with(||Buffer{rows:vec![],bytes:0,through:through_index,chunk:matches!(step,3|10|17).then(TrendChunk::default)});let encoded=if let Some(chunk)=&mut buffer.chunk{chunk.encode(row,&mut self.evidence)}else{canonical(row).and_then(|encoded|{require(encoded.len()<=MAX_EXPANDED_BYTES,"calculation row exceeds limit")?;Ok((row.clone(),encoded.len()))})};self.steps[index].encoding_seconds+=started.elapsed().as_secs_f64();self.steps[index].reused_bytes+=self.evidence.reused_bytes-reused;
        match encoded{Ok((value,size))=>{buffer.rows.push(value);buffer.bytes=buffer.bytes.saturating_add(size);buffer.through=through_index;self.steps[index].rows+=1;self.steps[index].encoded_bytes=self.steps[index].encoded_bytes.saturating_add(size);let full=buffer.bytes>=512*1024||buffer.chunk.as_ref().is_some_and(TrendChunk::full);if full{self.flush(step);}},Err(error)=>{self.steps[index].cache="failed".into();self.steps[index].error=Some(error.to_string());self.stop_cache();}}Ok(())
    }
    pub fn append(&mut self,step:u8,row:&Value)->StoreResult<()>{let index=row.get("known_at").and_then(Value::as_u64).or_else(||row.get("bar_index").and_then(Value::as_u64)).or_else(||row.get("index").and_then(Value::as_u64)).and_then(|v|usize::try_from(v).ok()).ok_or_else(||StoreError("calculation row requires explicit known index".into()))?;self.append_at(step,index,row)}
    fn stop_cache(&mut self){self.cache_disabled=true;self.buffers.clear();self.evidence.clear();for row in &mut self.steps{if row.status=="running"&&row.cache!="available"{row.cache="partial".into();if row.error.is_none(){row.error=Some("缓存写入中断，本轮停止缓存；计算继续".into());}}}}
    fn flush(&mut self,step:u8){let Some(buffer)=self.buffers.remove(&step)else{return;};if buffer.rows.is_empty(){return;}let row=&self.steps[step as usize-1];let key=json!({"input":self.inputs,"attempt":self.attempt,"step":step,"chunk":row.chunks.len()});let count=buffer.rows.len();let payload=if let Some(chunk)=buffer.chunk{chunk.finish(buffer.rows)}else{json!(buffer.rows)};let started=Instant::now();let stored=canonical(&payload).ok().filter(|bytes|bytes.len()<=MAX_EXPANDED_BYTES).map(|bytes|(sha256(bytes),self.cache.as_ref().is_some_and(|cache|cache.put("calculation-chunk",&key,&payload))));self.steps[step as usize-1].write_seconds+=started.elapsed().as_secs_f64();if let Some((digest,true))=stored{self.steps[step as usize-1].chunks.push(CalculationChunkRef{key,sha256:digest,rows:count,through_index:buffer.through});}else{self.stop_cache();}}
    fn save(&mut self)->bool{if !self.record_details||self.cache_disabled{return false;}let Some(inputs)=self.inputs.as_ref()else{return false;};let mut rows=self.steps.clone();for row in &mut rows{if row.cache=="available"{row.cache="stored".into();}}let manifest=json!({"steps":rows,"requested_order":self.plan.requested_order,"execution_order":self.plan.execution_order});let saved=self.cache.as_ref().is_some_and(|cache|cache.put("calculation-manifest",inputs,&manifest));if !saved{self.stop_cache();for row in &mut self.steps{if row.cache=="stored"{row.cache="partial".into();row.error=Some("缓存清单写入中断".into());}}}saved}
    pub fn complete(&mut self,step:u8)->StoreResult<()>{if self.row(step)?.status=="completed"{return Ok(());}self.begin(step)?;self.flush(step);let row=&mut self.steps[step as usize-1];row.status="completed".into();row.elapsed_seconds=self.started.get(&step).map_or(0.0,|t|t.elapsed().as_secs_f64());if self.record_details&&!matches!(row.cache.as_str(),"failed"|"available"|"partial"){row.cache=if self.cache.is_some(){"stored"}else{"failed"}.into();}self.save();Ok(())}
    pub fn finish(&mut self,result:Option<&Value>,error:Option<&str>)->StoreResult<()>{if error.is_none(){if let Some(result)=result.filter(|v|v.is_object()){if self.bar_count>0{let row:crate::indexed_json::Map<String,Value>=["signals","audit","orders","trades","curve","metrics","backtest"].iter().filter_map(|key|result.get(*key).map(|v|((*key).into(),v.clone()))).collect();self.append_at(24,self.bar_count-1,&Value::Object(row))?;self.complete(24)?;if result["backtest"]["status"]=="data_unavailable"{self.steps[23].status="failed".into();self.steps[23].error=Some("同源分钟数据不足，交易回测未完成".into());}}}}
        for step in 1..=24{if self.steps[step-1].status=="running"{self.flush(step as u8);let row=&mut self.steps[step-1];row.status="failed".into();row.error=Some(error.unwrap_or("步骤未完成").into());if !matches!(row.cache.as_str(),"available"|"failed"|"partial"){row.cache=if row.chunks.is_empty(){"none"}else{"partial"}.into();}}else if self.steps[step-1].status=="pending"{let row=&mut self.steps[step-1];if error.is_none()&&row.cache=="available"{row.status="completed".into();}else{row.status="not_recorded".into();row.error=Some(if error.is_some(){"前序计算失败，未执行此步骤"}else{"当前策略未提供此步骤"}.into());}}}self.save();self.evidence.clear();Ok(())
    }
    pub fn reuse_certificate(&self,step:u8,asof_index:usize)->StoreResult<Option<CalculationReuseCertificate>>{let row=self.row(step)?;if step==24||!matches!(row.cache.as_str(),"stored"|"available")||row.through_index.is_none_or(|i|i>asof_index){return Ok(None);}let Some(inputs)=self.inputs.as_ref()else{return Ok(None);};let required=|name:&str|inputs[name].as_str().map(str::to_owned).ok_or_else(||StoreError("calculation input certificate missing".into()));let certificate=CalculationReuseCertificate{schema:2,timeframe:required("timeframe")?,trend_level:step_level(step),market_sha256:required("market_sha256")?,request_sha256:required("request_sha256")?,engine_sha256:required("engine_sha256")?,bar_count:self.bar_count,step,through_index:row.through_index.unwrap_or(0),chunks_sha256:sha256(canonical(&json!(row.chunks))?)};Ok(Some(certificate))}
    pub fn read_chunk(&self,certificate:&CalculationReuseCertificate,index:usize,asof_index:usize)->StoreResult<Option<Vec<Value>>>{if self.reuse_certificate(certificate.step,asof_index)?.as_ref()!=Some(certificate){return Ok(None);}let row=self.row(certificate.step)?;let Some(reference)=row.chunks.get(index)else{return Ok(None);};if reference.through_index>asof_index{return Ok(None);}let Some(cache)=&self.cache else{return Ok(None);};let Some(payload)=cache.get("calculation-chunk",&reference.key)else{return Ok(None);};if sha256(canonical(&payload)?)!=reference.sha256{return Ok(None);}let restored=restore_calculation_chunk(&payload)?;require(restored.len()==reference.rows,"calculation chunk row count mismatch")?;Ok(Some(restored))}
    pub fn chunk_count(&self,step:u8)->StoreResult<usize>{Ok(self.row(step)?.chunks.len())}
}